package org.eclipse.rdf4j.query.algebra.evaluation.impl.restrictions;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.ArrayBindingBasedQueryEvaluationContext;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class RestrictionResultCacheTest {
	@Test
	void onlyCompleteTupleResponsesCanBeReusedAndKeepAllColumns() {
		var context = new ArrayBindingBasedQueryEvaluationContext(new QueryEvaluationContext.Minimal(null),
				new String[] { "x", "y" }, null);
		var layout = new RestrictionLayout(List.of("x", "y"), context);
		var vf = SimpleValueFactory.getInstance();
		var a = vf.createIRI("urn:a");
		var b = vf.createIRI("urn:b");
		var xy = layout.unrestricted().restrict(0, a).restrict(1, b);
		var yx = layout.unrestricted().restrict(0, b).restrict(1, a);
		var onlyX = layout.unrestricted().restrict(0, a);
		AtomicInteger opens = new AtomicInteger();
		RestrictedInvocation delegate = frame -> {
			opens.incrementAndGet();
			var row = new MapBindingSet();
			row.addBinding("x", frame.value(0));
			if (frame.value(1) != null) {
				row.addBinding("y", frame.value(1));
			}
			row.addBinding("opaqueOutput", vf.createLiteral(frame.unboundOnly(1) ? "absent" : "preserve"));
			return new CloseableIteratorIteration<>(List.<BindingSet>of(row, row).iterator());
		};
		try (var cache = new RestrictionResultCache(delegate, null, new Join())) {
			try (var partial = cache.probe(xy)) {
				partial.next();
			}
			var first = QueryResults.asList(cache.probe(xy));
			assertThat(first).hasSize(2);
			assertThat(QueryResults.asList(cache.probe(yx))).allMatch(row -> row.getValue("x").equals(b));
			assertThat(QueryResults.asList(cache.probe(onlyX))).noneMatch(row -> row.hasBinding("y"));
			assertThat(QueryResults.asList(cache.probe(onlyX.restrict(1, null))))
					.allMatch(row -> vf.createLiteral("absent").equals(row.getValue("opaqueOutput")));
			assertThat(QueryResults.asList(cache.probe(xy))).containsExactlyElementsOf(first);
			assertThat(opens).hasValue(5);
		}
	}
}
